      "name": "index.ts",
      "content": "import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "GET") {
    return Response.json(
      { error: "Method not allowed" },
      { status: 405, headers: corsHeaders },
    );
  }

  const apiKey = Deno.env.get("WEATHER_API_KEY");
  if (!apiKey) {
    console.error("WEATHER_API_KEY is not configured");
    return Response.json(
      { error: "Weather service is unavailable" },
      { status: 503, headers: corsHeaders },
    );
  }

  const location = new URL(req.url).searchParams.get("q")?.trim();
  if (!location) {
    return Response.json(
      { error: "The q query parameter is required" },
      { status: 400, headers: corsHeaders },
    );
  }

  const upstream = new URL("https://api.weatherapi.com/v1/current.json");
  upstream.searchParams.set("key", apiKey);
  upstream.searchParams.set("q", location);
  upstream.searchParams.set("aqi", "no");

  try {
    const response = await fetch(upstream);
    const body = await response.text();
    return new Response(body, {
      status: response.status,
      headers: {
        ...corsHeaders,
        "Content-Type": response.headers.get("Content-Type") ?? "application/json",
        "Cache-Control": "public, max-age=300",
      },
    });
  } catch (error) {
    console.error("WeatherAPI request failed", error);
    return Response.json(
      { error: "Weather service is unavailable" },
      { status: 502, headers: corsHeaders },
    );
  }
});
